window.SEARCH_INDEX = [{"t": "Brimstone", "s": "Agents", "u": "agents.html#brimstone", "d": "Контролёр. Ставит дымы с воздуха, бьёт зажигательным снарядом и вызывает орбитальный удар по выбранной зоне."}, {"t": "Viper", "s": "Agents", "u": "agents.html#viper", "d": "Контролёр. Мастер токсичных завес и ядовитых зон: перекрывает карту газом и ослабляет врагов внутри него."}, {"t": "Omen", "s": "Agents", "u": "agents.html#omen", "d": "Контролёр. Ставит теневые дымы, слепит врагов и телепортируется по карте, появляясь там, где его не ждут."}, {"t": "Astra", "s": "Agents", "u": "agents.html#astra", "d": "Контролёр. Расставляет звёзды по всей карте и активирует их как дым, гравитационный колодец или оглушающий взрыв."}, {"t": "Harbor", "s": "Agents", "u": "agents.html#harbor", "d": "Контролёр. Управляет водой: поднимает стены, накрывает позицию куполом и запускает волну, замедляющую врагов."}, {"t": "Clove", "s": "Agents", "u": "agents.html#clove", "d": "Контролёр. Дымит и ослабляет врагов, получает бонусы после убийств и может вернуться в бой даже после смерти."}, {"t": "Jett", "s": "Agents", "u": "agents.html#jett", "d": "Дуэлянт. Подвижный дуэлянт: быстрый рывок, подъём вверх, дымовые облака и набор метательных ножей."}, {"t": "Phoenix", "s": "Agents", "u": "agents.html#phoenix", "d": "Дуэлянт. Работает с огнём: ослепляет, ставит огненные стены, лечится в пламени и может откатиться на точку возрождения."}, {"t": "Reyna", "s": "Agents", "u": "agents.html#reyna", "d": "Дуэлянт. Питается душами убитых врагов: после убийства лечится или становится невидимой."}, {"t": "Raze", "s": "Agents", "u": "agents.html#raze", "d": "Дуэлянт. Взрывчатка и гранаты: кластерная граната, подрывной ранец и мощная ракета для зачистки позиции."}, {"t": "Yoru", "s": "Agents", "u": "agents.html#yoru", "d": "Дуэлянт. Играет на обмане: телепорт, ложные шаги, ослепляющая вспышка и переход в параллельное измерение."}, {"t": "Neon", "s": "Agents", "u": "agents.html#neon", "d": "Дуэлянт. Очень быстрый агент с электрическими стенами и мощным режимом ускорения со стрельбой лучом."}, {"t": "Iso", "s": "Agents", "u": "agents.html#iso", "d": "Дуэлянт. Защищается энергетическим щитом после убийств и вызывает соперника на дуэль один на один."}, {"t": "Waylay", "s": "Agents", "u": "agents.html#waylay", "d": "Дуэлянт. Дуэлянт, построенный вокруг скорости и мобильности. Подходит тем, кто любит быстрые входы на точку."}, {"t": "Sova", "s": "Agents", "u": "agents.html#sova", "d": "Инициатор. Разведка стрелами и дроном: показывает, где враги, и бьёт по ним сквозь стены."}, {"t": "Breach", "s": "Agents", "u": "agents.html#breach", "d": "Инициатор. Вспышки, ударные волны и оглушение, которые действуют сквозь стены и открывают проход команде."}, {"t": "Skye", "s": "Agents", "u": "agents.html#skye", "d": "Инициатор. Выпускает животных для разведки и вспышки, лечит союзников и помогает безопасно входить на точку."}, {"t": "KAY/O", "s": "Agents", "u": "agents.html#kayo", "d": "Инициатор. Робот, который подавляет способности врагов: отключает их навыки и мешает играть через гаджеты."}, {"t": "Fade", "s": "Agents", "u": "agents.html#fade", "d": "Инициатор. Использует кошмары: находит врагов, помечает их и мешает им слышать и видеть."}, {"t": "Gekko", "s": "Agents", "u": "agents.html#gekko", "d": "Инициатор. Командует существами, которые разведывают, ослепляют, ставят и разминируют спайк, а потом возвращаются."}, {"t": "Tejo", "s": "Agents", "u": "agents.html#tejo", "d": "Инициатор. Использует дрон и высокоточные ракетные удары, чтобы разведывать и выбивать врагов с позиций."}, {"t": "Sage", "s": "Agents", "u": "agents.html#sage", "d": "Страж. Лечит и воскрешает союзников, замедляет врагов и ставит ледяную стену для защиты прохода."}, {"t": "Cypher", "s": "Agents", "u": "agents.html#cypher", "d": "Страж. Держит территорию с помощью камеры и растяжек, видит перемещения врагов издалека."}, {"t": "Killjoy", "s": "Agents", "u": "agents.html#killjoy", "d": "Страж. Ставит турель и гаджеты-ловушки, а сильный ультимейт запирает врагов на участке карты."}, {"t": "Chamber", "s": "Agents", "u": "agents.html#chamber", "d": "Страж. Точный стрелок: свои пистолеты, ловушка-радар, телепорт на запасную позицию и мощная снайперская винтовка."}, {"t": "Deadlock", "s": "Agents", "u": "agents.html#deadlock", "d": "Страж. Блокирует проходы сенсорами, гравитационной сетью и захватывает врагов в кокон."}, {"t": "Vyse", "s": "Agents", "u": "agents.html#vyse", "d": "Страж. Использует металлические лозы и ловушки, которые мешают врагам и отключают оружие на точке."}, {"t": "Veto", "s": "Agents", "u": "agents.html#veto", "d": "Страж. Страж, который делает упор на защиту точек и устойчивость к способностям противников."}, {"t": "Summit", "s": "Maps", "u": "maps.html#summit", "d": "Карта из актуальной соревновательной ротации. Проверьте расположение точек в клиенте игры."}, {"t": "Abyss", "s": "Maps", "u": "maps.html#abyss", "d": "Карта, у которой нет ограждения по краям: можно упасть в пропасть. Много вертикальных позиций."}, {"t": "Sunset", "s": "Maps", "u": "maps.html#sunset", "d": "Две точки в стилизованном Лос-Анджелесе. Тесные улочки и центральная зона, которую важно удерживать."}, {"t": "Lotus", "s": "Maps", "u": "maps.html#lotus", "d": "Три точки и вращающиеся двери, которые меняют проходы. Огромное поле для командных тактик."}, {"t": "Corrode", "s": "Maps", "u": "maps.html#corrode", "d": "Карта из актуальной соревновательной ротации. Проверьте расположение точек в клиенте игры."}, {"t": "Haven", "s": "Maps", "u": "maps.html#haven", "d": "Первая карта с тремя точками. Требует хорошей ротации и контроля центральной зоны."}, {"t": "Bind", "s": "Maps", "u": "maps.html#bind", "d": "Классика без центра: попасть с точки на точку помогают телепорты. Много ловушек в узких проходах."}, {"t": "Icebox", "s": "Maps", "u": "maps.html#icebox", "d": "Вертикальная карта на промёрзшей базе: тросы, ящики и множество уровней высоты."}, {"t": "Pearl", "s": "Maps", "u": "maps.html#pearl", "d": "Подводный город без особых механик. Акцент на чистом контроле позиций и работе с центром."}, {"t": "Fracture", "s": "Maps", "u": "maps.html#fracture", "d": "Нестандартная карта в форме буквы H: атакующие стартуют с двух сторон, а тросы дают быстрые перемещения."}, {"t": "Breeze", "s": "Maps", "u": "maps.html#breeze", "d": "Большая открытая карта тропического острова. Длинные линии обзора и перестрелки на дистанции."}, {"t": "Ascent", "s": "Maps", "u": "maps.html#ascent", "d": "Классическая карта с двумя точками и закрывающимися дверями в центре, влияющими на ротации."}, {"t": "Split", "s": "Maps", "u": "maps.html#split", "d": "Две точки и центральная зона с верёвками. Вертикальный бой и контроль середины — основа карты."}, {"t": "Classic", "s": "Weapons", "u": "weapons.html#classic", "d": "Пистолеты. Стартовый пистолет. Бесплатный, подходит для экономичных раундов."}, {"t": "Shorty", "s": "Weapons", "u": "weapons.html#shorty", "d": "Пистолеты. Дробовик-пистолет: мощный вблизи, бесполезен на дистанции."}, {"t": "Frenzy", "s": "Weapons", "u": "weapons.html#frenzy", "d": "Пистолеты. Автоматический пистолет с высокой скорострельностью."}, {"t": "Ghost", "s": "Weapons", "u": "weapons.html#ghost", "d": "Пистолеты. Точный пистолет с глушителем. Хороший выбор на пистолетные раунды."}, {"t": "Bandit", "s": "Weapons", "u": "weapons.html#bandit", "d": "Пистолеты. Пистолет с упором на точность при быстрой стрельбе очередями."}, {"t": "Sheriff", "s": "Weapons", "u": "weapons.html#sheriff", "d": "Пистолеты. Мощный револьвер: при точном попадании убивает с одного-двух выстрелов."}, {"t": "Stinger", "s": "Weapons", "u": "weapons.html#stinger", "d": "Пистолеты-пулемёты. Скорострельный пистолет-пулемёт для ближнего боя."}, {"t": "Spectre", "s": "Weapons", "u": "weapons.html#spectre", "d": "Пистолеты-пулемёты. Универсальный ПП: хорошая точность и стабильный урон."}, {"t": "Bucky", "s": "Weapons", "u": "weapons.html#bucky", "d": "Дробовики. Классический дробовик. Мощный на ближних дистанциях."}, {"t": "Judge", "s": "Weapons", "u": "weapons.html#judge", "d": "Дробовики. Скорострельный дробовик для очень тесных пространств."}, {"t": "Bulldog", "s": "Weapons", "u": "weapons.html#bulldog", "d": "Винтовки. Автомат со вторичным режимом стрельбы очередями и приближением."}, {"t": "Guardian", "s": "Weapons", "u": "weapons.html#guardian", "d": "Винтовки. Полуавтоматическая винтовка для точных одиночных выстрелов."}, {"t": "Phantom", "s": "Weapons", "u": "weapons.html#phantom", "d": "Винтовки. Бесшумная винтовка с низкой отдачей, хорошо подходит для стрельбы через дымы."}, {"t": "Vandal", "s": "Weapons", "u": "weapons.html#vandal", "d": "Винтовки. Мощная винтовка, убивающая в голову с одного выстрела на любой дистанции."}, {"t": "Marshal", "s": "Weapons", "u": "weapons.html#marshal", "d": "Снайперские винтовки. Лёгкая снайперская винтовка, дешевле Operator, с высокой подвижностью."}, {"t": "Outlaw", "s": "Weapons", "u": "weapons.html#outlaw", "d": "Снайперские винтовки. Снайперская винтовка с двумя зарядами и быстрой перезарядкой."}, {"t": "Operator", "s": "Weapons", "u": "weapons.html#operator", "d": "Снайперские винтовки. Самая мощная винтовка в игре: убивает одним попаданием."}, {"t": "Ares", "s": "Weapons", "u": "weapons.html#ares", "d": "Пулемёты. Лёгкий пулемёт с большим магазином и высокой огневой мощью."}, {"t": "Odin", "s": "Weapons", "u": "weapons.html#odin", "d": "Пулемёты. Тяжёлый пулемёт: высокая скорострельность и отличная пробиваемость."}, {"t": "Unrated", "s": "Game Modes", "u": "modes.html#unrated", "d": "Стандартный командный режим 5 на 5 без рейтинга: нападение против обороны, спайк, до 13 побед в раундах."}, {"t": "Competitive", "s": "Game Modes", "u": "modes.html#competitive", "d": "Тот же формат, но с рейтингом и рангом. Победы и поражения двигают вас по лестнице рангов."}, {"t": "Swiftplay", "s": "Game Modes", "u": "modes.html#swiftplay", "d": "Сокращённая версия стандартного матча: меньше раундов, быстрый матч на 15–20 минут."}, {"t": "Spike Rush", "s": "Game Modes", "u": "modes.html#spike-rush", "d": "Короткие раунды, у всех одинаковое снаряжение и случайные усиления. Хорош для быстрой игры."}, {"t": "Deathmatch", "s": "Game Modes", "u": "modes.html#deathmatch", "d": "Бой каждый сам за себя: побеждает первый, набравший нужное число убийств."}, {"t": "Team Deathmatch", "s": "Game Modes", "u": "modes.html#team-deathmatch", "d": "Командный бой без спайка: две команды сражаются до установленного числа убийств."}, {"t": "Escalation", "s": "Game Modes", "u": "modes.html#escalation", "d": "Каждое убийство меняет оружие на следующее в списке. Побеждает команда, которая быстрее пройдёт все ступени."}, {"t": "Replication", "s": "Game Modes", "u": "modes.html#replication", "d": "Все игроки одной команды играют одним и тем же агентом, что приводит к необычным комбинациям способностей."}, {"t": "Premier", "s": "Game Modes", "u": "modes.html#premier", "d": "Организованный режим для постоянных команд с расписанием матчей и турнирной сеткой."}, {"t": "The Range", "s": "Game Modes", "u": "modes.html#the-range", "d": "Тренировочная зона: можно стрелять по ботам и мишеням, изучать способности агентов и настраивать прицел."}, {"t": "История игры", "s": "About", "u": "about.html#history", "d": "История создания VALORANT."}, {"t": "Riot Games", "s": "About", "u": "about.html#riot", "d": "Информация о разработчике Riot Games."}, {"t": "Интересные факты", "s": "About", "u": "about.html#facts", "d": "Интересные факты о VALORANT."}];
